B.aoc=new A.pG(B.vJ,"Operasyon ve Ticket Y\xf6netimi","A\xe7\u0131k ticketlar\u0131, i\u015f emirlerini ve durumlar\u0131n\u0131 listeler. M\xfc\u015fteri ad\u0131na yeni bir ticket a\xe7abilir, mevcut talebi teknisyene atayarak operasyona d\xf6n\xfc\u015ft\xfcrebilir.",B.Yu)
B.Xa=s(["Uzmanl\u0131k ve i\u015f y\xfck\xfcne g\xf6re teknisyen listesi","Teknisyen detay\u0131: deneyim, ileti\u015fim, performans","Aktif, tamamlanan ve bekleyen i\u015f da\u011f\u0131l\u0131m\u0131"],t.s)
B.aoa=new A.pG(B.oN,"Teknisyen Y\xf6netimi","Teknisyenleri ad, uzmanl\u0131k alan\u0131, ileti\u015fim bilgisi ve i\u015f y\xfck\xfcne g\xf6re arar. Tek bir teknisyenin profilini, tamamlama oran\u0131n\u0131 ve son i\u015flerini detayl\u0131 verir.",B.Xa)
B.a09=s(["Kritik stok ve toplam envanter \xf6zeti","Stok kart\u0131, birim fiyat ve miktar sorgusu","Stok giri\u015f/\xe7\u0131k\u0131\u015f hareketleri ve rezervasyonlar"],t.s)
B.ao7=new A.pG(B.eG,"Stok ve Yedek Par\xe7a","Kritik stok seviyesini, mevcut ve rezerve miktarlar\u0131 raporlar. Par\xe7a hareketlerini ve rezervasyon durumunu tarih aral\u0131\u011f\u0131na g\xf6re inceler.",B.a09)
B.Wr=s(["Alacak, bor\xe7 ve tahsilat \xf6zeti","Vadesi ge\xe7en fatura listesi","Cari hesap bakiyesi ve ekstre hareketleri"],t.s)
B.ao8=new A.pG(B.eH,"Muhasebe ve Finans","Alacak, bor\xe7, fatura ve tahsilat toplamlar\u0131n\u0131 verir. Vadesi ge\xe7en faturalar\u0131, cari hesap bakiyelerini ve ekstre hareketlerini sorgular.",B.Wr)
B.T7=new A.aF(62058,"MaterialIcons",!1)
B.Zj=s(["M\xfc\u015fteri ve cihaz say\u0131lar\u0131, garanti da\u011f\u0131l\u0131m\u0131","M\xfc\u015fteri arama ve detay sorgusu","Cihaz ar\u0131za ge\xe7mi\u015fi ve garanti biti\u015f tarihi"],t.s)
B.aob=new A.pG(B.T7,"M\xfc\u015fteri ve Cihaz","M\xfc\u015fteri say\u0131s\u0131n\u0131, cihaz envanterini ve garanti durumunu raporlar. Bir m\xfc\u015fterinin cihazlar\u0131n\u0131 ar\u0131za kayd\u0131 ve garanti biti\u015f tarihiyle listeler.",B.Zj)
B.a_F=s(["\xc7al\u0131\u015fan, izin ve avans \xf6zeti","Departman ve unvan baz\u0131nda personel listesi","Ayl\u0131k performans ve gecikme analizi"],t.s)
B.ao9=new A.pG(B.vK,"\u0130nsan Kaynaklar\u0131","\xc7al\u0131\u015fan say\u0131s\u0131n\u0131, izin durumunu ve avans taleplerini \xf6zetler. Ayl\u0131k performans raporlar\u0131n\u0131 tamamlanan, geciken i\u015f ve \xf6d\xfcl/ceza verileriyle verir.",B.a_F)
